#!/usr/bin/env python3
from __future__ import annotations
import hashlib,json,os,platform
from datetime import datetime,timezone,timedelta
from pathlib import Path
import psycopg
from psycopg.rows import dict_row

HERE=Path(__file__).resolve().parent
DSN=os.environ.get('PG_DSN','postgresql://postgres:postgres@127.0.0.1:5432/postgres')
def now(): return datetime.now(timezone.utc)
def canon(x): return json.dumps(x,sort_keys=True,separators=(',',':'),default=str)
def sha(x): return hashlib.sha256(canon(x).encode()).hexdigest()
def limit(value,unit,scope,source,ts,failure): return {'value':value,'unit':unit,'scope':scope,'source':source,'observed_at':ts,'failure_behavior':failure}

def main():
    started=now(); ts=started.isoformat().replace('+00:00','Z'); tests=[]
    def record(test_id,passed,evidence): tests.append({'test_id':test_id,'passed':bool(passed),'evidence':evidence})
    with psycopg.connect(DSN,autocommit=True,row_factory=dict_row) as admin:
        version=admin.execute("select current_setting('server_version') v, current_setting('server_version_num') n, current_setting('wal_level') wal_level").fetchone()
        record('server_identity_and_logical_wal',str(version['n']).startswith('18') and version['wal_level']=='logical',version)
        admin.execute('drop table if exists b08_items cascade')
        admin.execute('create table b08_items(id bigint primary key, value text not null, amount numeric(12,2), updated_at timestamptz not null default clock_timestamp())')
        admin.execute("insert into b08_items(id,value,amount) values (1,'alpha',1.20),(2,'beta',2.00)")
        cols=admin.execute("select column_name,data_type,is_nullable from information_schema.columns where table_schema='public' and table_name='b08_items' order by ordinal_position").fetchall()
        pk=admin.execute("select a.attname from pg_index i join pg_attribute a on a.attrelid=i.indrelid and a.attnum=any(i.indkey) where i.indrelid='public.b08_items'::regclass and i.indisprimary").fetchall()
        record('schema_and_key_discovery',any(r['column_name']=='id' for r in cols) and [r['attname'] for r in pk]==['id'],{'columns':cols,'primary_key':[r['attname'] for r in pk]})
        # REPEATABLE READ snapshot remains stable while another transaction commits.
        with psycopg.connect(DSN,autocommit=False) as reader, psycopg.connect(DSN,autocommit=False) as writer:
            reader.execute('set transaction isolation level repeatable read')
            before=reader.execute('select count(*) from b08_items').fetchone()[0]
            writer.execute("insert into b08_items(id,value,amount) values (3,'concurrent',3.00)"); writer.commit()
            during=reader.execute('select count(*) from b08_items').fetchone()[0]; reader.commit()
            after=reader.execute('select count(*) from b08_items').fetchone()[0]
            record('repeatable_snapshot_stability',before==during and after==before+1,{'before':before,'during_snapshot':during,'after_new_transaction':after})
        with psycopg.connect(DSN,autocommit=False) as tx:
            tx.execute("insert into b08_items(id,value,amount) values (99,'rollback',99.00)"); tx.rollback()
        rb=admin.execute('select count(*) c from b08_items where id=99').fetchone()['c']
        record('transaction_rollback_atomicity',rb==0,{'rows_after_rollback':rb})
        # Create a publication and a logical slot. Slot creation gives an exact LSN boundary.
        admin.execute('drop publication if exists b08_pub')
        admin.execute('create publication b08_pub for table b08_items')
        try: admin.execute("select pg_drop_replication_slot('b08_slot')")
        except Exception: pass
        slot=admin.execute("select slot_name, lsn::text from pg_create_logical_replication_slot('b08_slot','pgoutput')").fetchone()
        slot_meta=admin.execute("select slot_name,plugin,slot_type,database,active,restart_lsn::text,confirmed_flush_lsn::text from pg_replication_slots where slot_name='b08_slot'").fetchone()
        record('logical_slot_identity',slot['slot_name']=='b08_slot' and slot_meta['plugin']=='pgoutput' and slot_meta['slot_type']=='logical',{'created':slot,'metadata':slot_meta})
        start_lsn=admin.execute('select pg_current_wal_lsn()::text lsn').fetchone()['lsn']
        admin.execute("insert into b08_items(id,value,amount) values (4,'cdc_insert',4.00)")
        admin.execute("update b08_items set amount=4.50,value='cdc_update' where id=4")
        admin.execute('delete from b08_items where id=2')
        end_lsn=admin.execute('select pg_current_wal_lsn()::text lsn').fetchone()['lsn']
        diff=admin.execute('select pg_wal_lsn_diff(%s::pg_lsn,%s::pg_lsn) d',(end_lsn,start_lsn)).fetchone()['d']
        record('wal_position_advances_for_changes',diff>0,{'start_lsn':start_lsn,'end_lsn':end_lsn,'byte_diff':str(diff)})
        # pgoutput messages are binary. We prove that the logical slot observes non-empty changes,
        # but do not claim a Debezium/Airbyte decoding contract from this native SQL probe.
        changes=admin.execute("select lsn::text,xid,data from pg_logical_slot_peek_binary_changes('b08_slot',NULL,100,'proto_version','1','publication_names','b08_pub')").fetchall()
        record('logical_change_visibility',len(changes)>0,{'message_count':len(changes),'first_lsn':changes[0]['lsn'] if changes else None,'last_lsn':changes[-1]['lsn'] if changes else None})
        admin.execute('alter table b08_items add column note text')
        cols2=admin.execute("select column_name,data_type,is_nullable from information_schema.columns where table_schema='public' and table_name='b08_items' order by ordinal_position").fetchall()
        record('schema_evolution_discoverable',any(r['column_name']=='note' for r in cols2),{'columns':cols2})
        rows=admin.execute("select id,value,amount::text,note from b08_items order by id").fetchall()
        logical_digest=sha(rows); count=len(rows); ids=[r['id'] for r in rows]
        record('final_reconciliation',count==3 and ids==[1,3,4],{'row_count':count,'ids':ids,'logical_rowset_sha256':logical_digest})
        wal_keep=admin.execute("select current_setting('max_replication_slots') slots,current_setting('max_wal_senders') senders,current_setting('max_slot_wal_keep_size') keep").fetchone()
        all_pass=all(t['passed'] for t in tests)
