        (HERE/'source-occurrence.json').write_text(json.dumps(occ,indent=2,sort_keys=True,default=str)+'\n')
        offer={'offer_id':'source-offer.postgresql18.transactional_and_logical.current','provider':'PostgreSQL Global Development Group','product':'PostgreSQL','edition_or_version_envelope':'18.x; executed occurrence uses 18.6','source_class_refs':[occ['source_class_id'],'source.event_messaging_cdc.transaction_log_cdc'],'documented_object_families':['databases','schemas','tables','rows','WAL changes','publications','logical replication slots'],'documented_access_surface_kinds':['SQL database connection','logical replication protocol','logical decoding SQL interface'],'evidence_refs':['ev.postgresql.mvcc','https://www.postgresql.org/docs/18/logical-replication-config.html','https://www.postgresql.org/docs/18/logicaldecoding.html'],'status':'DOCUMENTED_OFFER_CANDIDATE','non_collapse':['PostgreSQL product != relational source class','PostgreSQL logical decoding offer != this configured occurrence','publication/slot != connector implementation','documented logical replication != successful external CDC acquisition'],'completion_claim':False}
